#!/usr/bin/env node
// The one look of both apps: design/theme.json -> three generated files (plain Node, no packages).
//   dream-ext/static/theme.css   every web page (book.html, options.html, vocab.html, reader.html) links it
//   dream-ext/src/theme.ts       the same CSS as text (the tutor lives in shadow roots: it needs the variables inside
//                                them), and the values for the scripts
//   ios/YTLearn/Theme.swift      the native screens: colours for light and dark, fonts, spacing, corners, one button style
// node scripts/make-theme.mjs           writes the three files (dream-ext/build.mjs runs it before every build)
// node scripts/make-theme.mjs --check   only checks that they are up to date (exit 1 when not)
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

export const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
export const SOURCE = path.join(ROOT, 'design/theme.json');
export const OUTPUTS = { css: 'dream-ext/static/theme.css', ts: 'dream-ext/src/theme.ts', swift: 'ios/YTLearn/Theme.swift' };

const kebab = (s) => s.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`);
const HEAD = 'GENERATED by scripts/make-theme.mjs from design/theme.json. Do not edit: change design/theme.json and build.';

/** the declarations that do not change between light and dark */
function fixedVars(t) {
  const v = [];
  for (const [k, f] of Object.entries(t.fonts)) v.push([`--t-font-${kebab(k)}`, f.css]);
  for (const [k, s] of Object.entries(t.type)) {
    v.push([`--t-size-${kebab(k)}`, `${s.size}px`]);
    v.push([`--t-weight-${kebab(k)}`, String(s.weight)]);
  }
  v.push(['--t-line-body', String(t.type.body.line)]);
  for (const [k, n] of Object.entries(t.space)) v.push([`--t-space-${k}`, `${n}px`]);
  for (const [k, n] of Object.entries(t.radius)) v.push([`--t-radius-${k}`, `${n}px`]);
  v.push(['--t-control', `${t.control.min}px`], ['--t-control-main', `${t.control.main}px`]);
  for (const [k, n] of Object.entries(t.motion)) v.push([`--t-${k}`, `${n}ms`]);
  return v;
}
/** the colours of one scheme (light or dark) */
function schemeVars(t, scheme) {
  const v = Object.entries(t.colors).map(([k, c]) => [`--t-${kebab(k)}`, c[scheme]]);
  v.push(['--t-shadow', t.shadow[scheme].css], ['color-scheme', scheme]);
  return v;
}
const block = (sel, vars) => `${sel} {\n${vars.map(([k, v]) => `  ${k}: ${v};`).join('\n')}\n}\n`;

/** for a page: :root follows the device; data-theme="light" / "dark" (on <html> or <body>) is a page's own choice */
export function cssFor(t) {
  return `/* ${HEAD} */\n`
    + block(':root', [...fixedVars(t), ...schemeVars(t, 'light')])
    + `@media (prefers-color-scheme: dark) {\n${block(':root:not([data-theme="light"])', schemeVars(t, 'dark')).replace(/^/gm, '  ').trimEnd()}\n}\n`
    + block('[data-theme="light"]', schemeVars(t, 'light'))
    + block('[data-theme="dark"]', schemeVars(t, 'dark'));
}
/** for a shadow root (the tutor): the host follows the device; its data-look="day" / "night" is the learner's choice */
export function hostCssFor(t) {
  return block(':host', [...fixedVars(t), ...schemeVars(t, 'light')])
    + `@media (prefers-color-scheme: dark) {\n${block(':host(:not([data-look="day"]))', schemeVars(t, 'dark')).replace(/^/gm, '  ').trimEnd()}\n}\n`
    + block(':host([data-look="night"])', schemeVars(t, 'dark'));
}

export function tsFor(t) {
  const colors = (scheme) => Object.fromEntries(Object.entries(t.colors).map(([k, c]) => [k, c[scheme]]));
  const px = (o) => Object.fromEntries(Object.entries(o).map(([k, v]) => [k, v]));
  return `/* ${HEAD} */
/** every token of the one look, light and dark (the same values as theme.css and Theme.swift) */
export type ColorToken = ${Object.keys(t.colors).map((k) => `'${k}'`).join(' | ')};
export type Palette = Readonly<Record<ColorToken, string>>;
export const TOKENS: { readonly light: Palette; readonly dark: Palette } = ${JSON.stringify({ light: colors('light'), dark: colors('dark') }, null, 2)};
export const FONTS = ${JSON.stringify(Object.fromEntries(Object.entries(t.fonts).map(([k, f]) => [k, f.css])), null, 2)} as const;
export const TYPE = ${JSON.stringify(Object.fromEntries(Object.entries(t.type).map(([k, s]) => [k, s.size])), null, 2)} as const;
export const SPACE = ${JSON.stringify(px(t.space))} as const;
export const RADIUS = ${JSON.stringify(px(t.radius))} as const;
export const CONTROL = ${JSON.stringify(t.control)} as const;
export const MOTION = ${JSON.stringify(t.motion)} as const;
/** theme.css as text: the variables for a document (follows the device; data-theme="light" / "dark" wins) */
export const THEME_CSS = ${JSON.stringify(cssFor(t))};
/** the same for a shadow root: put it first in the root's style (the host follows the device; data-look wins) */
export const THEME_HOST_CSS = ${JSON.stringify(hostCssFor(t))};
`;
}

const hex6 = (s) => /^#[0-9a-fA-F]{6}$/.test(s);
function swiftColor(v) {
  if (hex6(v)) return `0x${v.slice(1).toUpperCase()}, 1`;
  const m = /^rgba\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*([\d.]+)\s*\)$/.exec(v);
  if (!m) throw new Error(`theme.json: a colour Swift cannot read: ${v}`);
  const h = [m[1], m[2], m[3]].map((n) => (+n).toString(16).padStart(2, '0')).join('').toUpperCase();
  return `0x${h}, ${+m[4]}`;
}
const swiftWeight = (w) => (w >= 700 ? '.bold' : w >= 600 ? '.semibold' : w >= 500 ? '.medium' : '.regular');

export function swiftFor(t) {
  const colors = Object.entries(t.colors).map(([k, c]) => `    /// ${c.use}\n    static let ${k} = dynamic(light: (${swiftColor(c.light)}), dark: (${swiftColor(c.dark)}))`).join('\n');
  const type = Object.entries(t.type).map(([k, s]) => `    /// ${s.use} (${s.size} pt)\n    static let ${k} = Font.system(size: ${s.size}, weight: ${swiftWeight(s.weight)})`).join('\n');
  const sizes = Object.entries(t.type).map(([k, s]) => `        static let ${k}: CGFloat = ${s.size}`).join('\n');
  const space = Object.entries(t.space).map(([k, n]) => `        static let ${k}: CGFloat = ${n}`).join('\n');
  const radius = Object.entries(t.radius).map(([k, n]) => `        static let ${k}: CGFloat = ${n}`).join('\n');
  const sh = t.shadow;
  return `// ${HEAD}
import SwiftUI
import UIKit

/// The one look of both apps (the same values as the web pages' theme.css): colours that follow the iPhone's light
/// and dark setting, the fonts, the text sizes, the spacing, the corners and one button style.
enum Theme {
    /// a colour for light and one for dark (the iPhone's setting chooses)
    private static func dynamic(light: (UInt32, CGFloat), dark: (UInt32, CGFloat)) -> Color {
        Color(UIColor { traits in
            let (rgb, alpha) = traits.userInterfaceStyle == .dark ? dark : light
            return UIColor(red: CGFloat((rgb >> 16) & 0xFF) / 255, green: CGFloat((rgb >> 8) & 0xFF) / 255, blue: CGFloat(rgb & 0xFF) / 255, alpha: alpha)
        })
    }

    // ---- colours ----
${colors}

    // ---- fonts ----
${type}
    /// reading text: ${t.fonts.serif.css}
    static func serif(_ size: CGFloat, weight: Font.Weight = .regular) -> Font {
        UIFont(name: "${t.fonts.serif.swift}", size: size) != nil ? Font.custom("${t.fonts.serif.swift}", size: size).weight(weight) : Font.system(size: size, weight: weight, design: .serif)
    }
    /// Chinese
    static func zh(_ size: CGFloat) -> Font { Font.custom("${t.fonts.zh.swift}", size: size) }
    /// the smallest text of a bar's label (a caption, never smaller)
    static let barLabel = Font.system(size: ${Math.max(12, t.type.caption.size - 1)}, weight: .medium)

    enum TextSize {
${sizes}
    }
    enum Space {
${space}
    }
    enum Radius {
${radius}
    }
    enum Control {
        /// every button at least this tall (and wide)
        static let min: CGFloat = ${t.control.min}
        /// the main buttons
        static let main: CGFloat = ${t.control.main}
    }
    enum Motion {
        static let fast: Double = ${t.motion.fast / 1000}
        static let normal: Double = ${t.motion.normal / 1000}
    }
    /// the one soft shadow (light / dark)
    static let shadowColor = dynamic(light: (0x000000, ${sh.light.opacity}), dark: (0x000000, ${sh.dark.opacity}))
    static let shadowRadius: CGFloat = ${sh.light.radius}
    static let shadowY: CGFloat = ${sh.light.y}
}

/// The one button style of both apps (the web pages draw the same three):
/// .primary = filled with the accent; .secondary = raised with a line around it; .quiet = only the accent text.
struct ThemeButtonStyle: ButtonStyle {
    enum Kind { case primary, secondary, quiet }
    var kind: Kind = .secondary
    var main = false
    @Environment(\\.isEnabled) private var enabled

    func makeBody(configuration: Configuration) -> some View {
        configuration.label
            .font(Theme.button)
            .foregroundColor(kind == .primary ? Theme.accentText : kind == .quiet ? Theme.accent : Theme.text)
            .padding(.horizontal, Theme.Space.l)
            .frame(minWidth: Theme.Control.min, minHeight: main ? Theme.Control.main : Theme.Control.min)
            .background(
                RoundedRectangle(cornerRadius: Theme.Radius.control, style: .continuous)
                    .fill(kind == .primary ? Theme.accent : kind == .quiet ? Color.clear : Theme.raised)
            )
            .overlay(
                RoundedRectangle(cornerRadius: Theme.Radius.control, style: .continuous)
                    .stroke(kind == .secondary ? Theme.lineStrong : Color.clear, lineWidth: 1)
            )
            .contentShape(Rectangle())
            .opacity(enabled ? (configuration.isPressed ? 0.7 : 1) : 0.4)
            .animation(.easeOut(duration: Theme.Motion.fast), value: configuration.isPressed)
    }
}

/// a button of a bar: a symbol with a word under it, in the theme's colours; pressed = the hover colour behind it
struct ThemeBarButtonStyle: ButtonStyle {
    var tint: Color = Theme.text
    func makeBody(configuration: Configuration) -> some View {
        configuration.label
            .foregroundColor(tint)
            .background(
                RoundedRectangle(cornerRadius: Theme.Radius.control, style: .continuous)
                    .fill(configuration.isPressed ? Theme.hover : Color.clear)
            )
            .contentShape(Rectangle())
    }
}

extension ButtonStyle where Self == ThemeButtonStyle {
    static var themePrimary: ThemeButtonStyle { ThemeButtonStyle(kind: .primary) }
    static var themeSecondary: ThemeButtonStyle { ThemeButtonStyle(kind: .secondary) }
    static var themeQuiet: ThemeButtonStyle { ThemeButtonStyle(kind: .quiet) }
}
extension ButtonStyle where Self == ThemeBarButtonStyle {
    static var themeBar: ThemeBarButtonStyle { ThemeBarButtonStyle() }
}
`;
}

export function readTheme() { return JSON.parse(fs.readFileSync(SOURCE, 'utf8')); }
/** { relative path: what the file must contain } */
export function renderAll(t = readTheme()) {
  return { [OUTPUTS.css]: cssFor(t), [OUTPUTS.ts]: tsFor(t), [OUTPUTS.swift]: swiftFor(t) };
}
/** the generated files that differ from what theme.json gives (an empty list = up to date) */
export function stale() {
  return Object.entries(renderAll()).filter(([rel, text]) => { try { return fs.readFileSync(path.join(ROOT, rel), 'utf8') !== text; } catch { return true; } }).map(([rel]) => rel);
}
/** writes the files that changed; returns them */
export function writeTheme() {
  const changed = [];
  for (const [rel, text] of Object.entries(renderAll())) {
    const file = path.join(ROOT, rel);
    let old = null;
    try { old = fs.readFileSync(file, 'utf8'); } catch { /* new */ }
    if (old !== text) { fs.mkdirSync(path.dirname(file), { recursive: true }); fs.writeFileSync(file, text); changed.push(rel); }
  }
  return changed;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  if (process.argv.includes('--check')) {
    const s = stale();
    if (s.length) { console.error(`out of date with design/theme.json: ${s.join(', ')} (run node scripts/make-theme.mjs)`); process.exit(1); }
    console.log('theme files up to date');
  } else {
    const c = writeTheme();
    console.log(c.length ? `theme: wrote ${c.join(', ')}` : 'theme: up to date');
  }
}
